-- =============================================================================
-- 2. COMMENTS
-- =============================================================================
-- PROVEN: client uuid (client_id) makes retries idempotent -> our id IS the client uuid; root parent type 1 = task;
--   type 1 comment / 2 reply (+ post, email exist); body = ordered segments with mention snapshots; assignee_id; resolved;
--   thread_* counters; edit replaces the whole body.
-- ASSUMED: other parent types, one reply level, cached reply counters, soft delete.
CREATE TABLE comments (
  id                uuid PRIMARY KEY,
  workspace_id      uuid NOT NULL /* id -> access.workspaces */,
  parent_type       text NOT NULL CHECK (parent_type IN ('task','doc','page','list','goal','view')),
  parent_id         uuid NOT NULL,                   -- polymorphic, no FK (ASSUMED)
  parent_comment_id uuid REFERENCES comments(id),    -- thread root; NULL for top level
  kind              text NOT NULL DEFAULT 'comment' CHECK (kind IN ('comment','reply','post','email')),
  author_id         uuid NOT NULL /* id -> identity.users */,
  body              jsonb NOT NULL,                  -- rich text segments [{text, attributes}] + mention snapshots; payload only
  body_text         text NOT NULL DEFAULT '',        -- plain text extracted app-side (search, email digests)
  assignee_id       uuid /* id -> identity.users */,       -- PROVEN: assigned comment = action item
  assigned_by       uuid /* id -> identity.users */,
  resolved_at       timestamptz,                     -- PROVEN resolved:true; timestamp is ASSUMED
  resolved_by       uuid /* id -> identity.users */,
  reply_count       integer NOT NULL DEFAULT 0,      -- ASSUMED cache of derived thread_comment_count (root comments only)
  last_reply_at     timestamptz,                     -- cache of thread_latest_comment_date
  edited_at         timestamptz,
  deleted_at        timestamptz,
  deleted_by        uuid /* id -> identity.users */,
  created_at        timestamptz NOT NULL DEFAULT now(),   -- comment_date
  updated_at        timestamptz NOT NULL DEFAULT now(),
  version           integer NOT NULL DEFAULT 1,
  CHECK ((kind = 'reply') = (parent_comment_id IS NOT NULL)),
  CHECK (assignee_id IS NULL OR parent_comment_id IS NULL)   -- ASSUMED: only top-level comments can be assigned
);

-- comments panel on a task/doc, oldest first.
CREATE INDEX comments_parent ON comments (workspace_id, parent_type, parent_id, created_at) WHERE deleted_at IS NULL AND parent_comment_id IS NULL;

-- replies of a thread.
CREATE INDEX comments_replies ON comments (workspace_id, parent_comment_id, created_at) WHERE parent_comment_id IS NOT NULL AND deleted_at IS NULL;

-- 'my assigned comments' (action items) still open.
CREATE INDEX comments_assigned ON comments (workspace_id, assignee_id, created_at DESC)
  WHERE assignee_id IS NOT NULL AND resolved_at IS NULL AND deleted_at IS NULL;

-- activity by author.
CREATE INDEX comments_author ON comments (workspace_id, author_id, created_at DESC);

-- mentions extracted from body at write time (PROVEN: stored inside body; table is ASSUMED, for fan-out + 'mentions of me').
CREATE TABLE comment_mentions (
  comment_id   uuid NOT NULL REFERENCES comments(id) ON DELETE CASCADE,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  target_kind  text NOT NULL CHECK (target_kind IN ('user','team','agent','task','doc','location','comment')),  -- PROVEN list
  target_id    uuid NOT NULL,
  no_watch     boolean NOT NULL DEFAULT false,       -- PROVEN noWatch flag
  PRIMARY KEY (comment_id, target_kind, target_id)
);

CREATE INDEX comment_mentions_target ON comment_mentions (workspace_id, target_kind, target_id);

-- 'mentions of me', backlinks
CREATE TABLE comment_reactions (                     -- PROVEN: comment, user, emoji hex code
  comment_id   uuid NOT NULL REFERENCES comments(id) ON DELETE CASCADE,
  user_id      uuid NOT NULL /* id -> identity.users */,
  emoji        text NOT NULL,                        -- hex code e.g. 1F44D
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (comment_id, user_id, emoji)
);

CREATE INDEX comment_reactions_user ON comment_reactions (workspace_id, user_id);

-- reactions by a user (data export, user purge)

-- per-user thread read state (PROVEN: thread_last_read_date, has_unread_comments/mentions; unread count derived)
CREATE TABLE comment_read_state (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  comment_id uuid NOT NULL REFERENCES comments(id) ON DELETE CASCADE,
  last_read_at timestamptz,
  has_unread_mentions boolean NOT NULL DEFAULT false,
  PRIMARY KEY (user_id, comment_id)
);

CREATE INDEX comment_read_state_unread ON comment_read_state (workspace_id, user_id) WHERE has_unread_mentions;

-- preview worker (global)

-- attachment = a file (or external URL) attached to an object. PROVEN hidden_attachments on tasks.
CREATE TABLE attachments (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  parent_type text NOT NULL CHECK (parent_type IN ('task','comment','doc','page','goal','custom_field')),
  parent_id uuid NOT NULL,                           -- polymorphic; may precede the parent row (client ids)
  file_id uuid /* id -> files.files */,
  external_url text,                                 -- ASSUMED: Drive/Dropbox style link
  title text,
  hidden boolean NOT NULL DEFAULT false,
  position integer NOT NULL DEFAULT 0,
  created_by uuid /* id -> identity.users */,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  CHECK ((file_id IS NOT NULL) <> (external_url IS NOT NULL))
);

CREATE INDEX attachments_parent ON attachments (workspace_id, parent_type, parent_id, position) WHERE deleted_at IS NULL;

-- attachments of a task/comment
CREATE INDEX attachments_file ON attachments (workspace_id, file_id) WHERE file_id IS NOT NULL;
